CREATE TABLE public.editor_news_import_state (id text PRIMARY KEY, lease_until timestamptz, lease_owner uuid, last_completed_at timestamptz, last_error text, imported integer NOT NULL DEFAULT 0); GRANT SELECT ON public.editor_news_import_state TO authenticated; GRANT ALL ON public.editor_news_import_state TO service_role; ALTER TABLE public.editor_news_import_state ENABLE ROW LEVEL SECURITY; CREATE POLICY editor_news_state_read ON public.editor_news_import_state FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'editor'));